package com.mobileapi.storage

import java.io._
import java.nio.file._
import java.nio.file.attribute._
import java.security._
import javax.crypto._
import javax.crypto.spec._
import java.util.Base64
import scala.util.{Try, Success, Failure}
import scala.collection.concurrent.TrieMap

object EncryptedStorageService {
  private val SESSION_KEYS = new TrieMap[String, SecretKey]()
  private val BASE_DIR = "/var/mobile-api/encrypted-store"
  private val TEMP_DIR = "/var/mobile-api/tmp"

  def initializeKey(userId: String): SecretKey = {
    val keyGen = KeyGenerator.getInstance("AES")
    keyGen.init(256)
    val key = keyGen.generateKey()
    SESSION_KEYS.put(userId, key)
    key
  }

  def getKey(userId: String): Option[SecretKey] = SESSION_KEYS.get(userId)

  private def sanitizeFilename(name: String): String = {
    name.replaceAll("[^a-zA-Z0-9._-]", "_")
      .replaceAll("\\.{2,}", "_")
      .take(128)
  }

  private def encryptData(data: Array[Byte], key: SecretKey): Array[Byte] = {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, key)
    val iv = cipher.getIV()
    val encrypted = cipher.doFinal(data)
    iv ++ encrypted
  }

  private def decryptData(data: Array[Byte], key: SecretKey): Array[Byte] = {
    val iv = data.take(12)
    val encrypted = data.drop(12)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val spec = new GCMParameterSpec(128, iv)
    cipher.init(Cipher.DECRYPT_MODE, key, spec)
    cipher.doFinal(encrypted)
  }

  def resolveStoragePath(userId: String, filename: String): Path = {
    val sanitized = sanitizeFilename(filename)
    val userDir = Paths.get(BASE_DIR, sanitizeFilename(userId))
    Files.createDirectories(userDir)
    userDir.resolve(sanitized)
  }

  def prepareTempFile(userId: String, filename: String): Path = {
    val sanitized = sanitizeFilename(filename)
    val tempPath = Paths.get(TEMP_DIR, s"${sanitizeFilename(userId)}_${sanitized}.tmp")
    tempPath
  }

  def storeEncryptedFile(userId: String, filename: String, content: Array[Byte]): Either[String, String] = {
    getKey(userId) match {
      case None => Left("No session key found")
      case Some(key) =>
        Try {
          val tempFile = prepareTempFile(userId, filename)
          val targetFile = resolveStoragePath(userId, filename)

          // Write encrypted content to temp file first
          val encrypted = encryptData(content, key)
          Files.write(tempFile, encrypted, 
            StandardOpenOption.CREATE, 
            StandardOpenOption.WRITE,
            StandardOpenOption.TRUNCATE_EXISTING)

          // Verify temp file integrity before moving
          val verification = Files.readAllBytes(tempFile)
          val decrypted = decryptData(verification, key)

          if (!MessageDigest.isEqual(decrypted, content)) {
            Files.deleteIfExists(tempFile)
            throw new SecurityException("Integrity check failed")
          }

          // Atomic move from temp to target
          moveToTarget(tempFile, targetFile)

          targetFile.toString
        } match {
          case Success(path) => Right(path)
          case Failure(ex) => Left(s"Storage failed: ${ex.getMessage}")
        }
    }
  }

  private def moveToTarget(source: Path, target: Path): Unit = {
    // Check that target location is within expected directory.
    // Use a strict containment check to avoid sibling-prefix bypass
    // (e.g. "/var/mobile-api/encrypted-store-evil").
    val canonicalBaseFile = new File(BASE_DIR).getCanonicalFile
    val canonicalBase = canonicalBaseFile.getPath
    val canonicalTargetFile = target.toFile.getCanonicalFile
    val canonicalTarget = canonicalTargetFile.getPath
    val basePrefix = canonicalBase + File.separator

    if (!(canonicalTarget == canonicalBase || canonicalTarget.startsWith(basePrefix))) {
      throw new SecurityException("Path traversal detected")
    }

    // Reject if target is or contains a symbolic link
    if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
      val attrs = Files.readAttributes(target, classOf[BasicFileAttributes], LinkOption.NOFOLLOW_LINKS)
      if (attrs.isSymbolicLink()) {
        Files.deleteIfExists(source)
        throw new SecurityException("Symlink detected at target path, aborting")
      }
    }

    Files.move(source, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE)
  }

  def retrieveEncryptedFile(userId: String, filename: String): Either[String, Array[Byte]] = {
    getKey(userId) match {
      case None => Left("No session key found")
      case Some(key) =>
        Try {
          val targetFile = resolveStoragePath(userId, filename)

          if (!Files.exists(targetFile, LinkOption.NOFOLLOW_LINKS)) {
            throw new FileNotFoundException(s"File not found: $filename")
          }

          // Ensure we don't follow symlinks on read
          val attrs = Files.readAttributes(targetFile, classOf[BasicFileAttributes], LinkOption.NOFOLLOW_LINKS)
          if (attrs.isSymbolicLink()) {
            throw new SecurityException("Symlink detected, refusing to read")
          }

          val encrypted = Files.readAllBytes(targetFile)
          decryptData(encrypted, key)
        } match {
          case Success(data) => Right(data)
          case Failure(ex) => Left(s"Retrieval failed: ${ex.getMessage}")
        }
    }
  }

  def deleteFile(userId: String, filename: String): Either[String, Boolean] = {
    Try {
      val targetFile = resolveStoragePath(userId, filename)
      // Only delete regular files, not symlinks
      if (Files.exists(targetFile, LinkOption.NOFOLLOW_LINKS)) {
        val attrs = Files.readAttributes(targetFile, classOf[BasicFileAttributes], LinkOption.NOFOLLOW_LINKS)
        if (attrs.isSymbolicLink()) {
          throw new SecurityException("Cannot delete symlink")
        }
      }
      Files.deleteIfExists(targetFile)
    } match {
      case Success(deleted) => Right(deleted)
      case Failure(ex) => Left(s"Delete failed: ${ex.getMessage}")
    }
  }
}
